add_filter( 'the_content', 'perfectpixel_external_links_new_tab', 999 );

function perfectpixel_external_links_new_tab( $content ) {
	if ( is_admin() || is_feed() || false === stripos( $content, '<a' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
		return $content;
	}
	$site_host = strtolower( (string) wp_parse_url( home_url(), PHP_URL_HOST ) );
	$tags      = new WP_HTML_Tag_Processor( $content );
	while ( $tags->next_tag( 'a' ) ) {
		$href = (string) $tags->get_attribute( 'href' );
		if ( ! preg_match( '#^(https?:)?//#i', $href ) || null !== $tags->get_attribute( 'target' ) ) {
			continue;
		}
		$host = strtolower( (string) wp_parse_url( ( 0 === strpos( $href, '//' ) ? 'https:' : '' ) . $href, PHP_URL_HOST ) );
		if ( ! $host || $host === $site_host || 'www.' . $host === $site_host || $host === 'www.' . $site_host ) {
			continue;
		}
		$tags->set_attribute( 'target', '_blank' );
		$rel = trim( (string) $tags->get_attribute( 'rel' ) );
		if ( false === strpos( ' ' . $rel . ' ', ' noopener ' ) ) {
			$tags->set_attribute( 'rel', trim( $rel . ' noopener' ) );
		}
	}
	return $tags->get_updated_html();
}
